/* Kínálati vizsgálat: egyetlen forráslapból, fogásazonosító szerint csoportosítva. */
(()=>{'use strict';let restaurant='',query='',pizza=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>new Intl.NumberFormat('hu-HU').format(Math.round(n));const terms=[['Csirke',/csirk|tyúk|kakas|chicken/i],['Sertés',/sertés|sertes|karaj|szűzpecsenye|tarja|mangalica|császárhús|pork/i],['Marha',/marha|borjú|bélszín|hátszín|beef/i],['Kacsa',/kacsa|duck/i],['Hal és tenger gyümölcsei',/lazac|harcsa|tonhal|pisztráng|sügér|halfilé|tőkehal|rák|garnéla|kagyló|polip|tintahal|salmon|shrimp/i],['Gomba',/gomb[áa]|vargánya|champignon|shiitake/i],['Burgonya',/burgonya|krumpli|dödölle|hasábburgonya/i],['Sajt',/sajt|parmezán|gorgonzola|mozzarella|feta|cheddar|ricotta|camembert|gomolya|pecorino|burrata/i],['Paradicsom',/paradicsom|pomodoro|tomato/i],['Sütőtök',/sütőtök|sütő tök|pumpkin/i],['Cékla',/cékl[áa]|beetroot/i],['Padlizsán',/padlizsán|eggplant/i],['Tofu',/tofu/i],['Spenót',/spenót|spinach/i],['Káposzta',/káposzta|coleslaw/i],['Rizs',/rizs|rizottó|risotto/i],['Tészta',/tészta|spaghetti|spagetti|tagliatelle|pasta|rigatoni|penne|ravioli|udon/i]];
const cat=r=>{let s=(String(r[4]||'')+' '+String(r[27]||'')).toLowerCase();if(/sushi|maki|nigiri|teker(cs|ő)|uramaki/.test(s))return 'Sushi';if(/leves/.test(s))return 'Leves';if(/desszert|édesség/.test(s))return 'Desszert';if(/előétel/.test(s))return 'Előétel';if(/pizza|pinsa/.test(s))return 'Pizza / pinsa';if(/burger/.test(s))return 'Burger';if(/savanyúság|köret\s*\/\s*saláta/.test(s))return 'Köret / savanyúság';if(/saláta/.test(s))return 'Saláta';if(/tészta|pasta/.test(s))return 'Tészta';if(/főétel/.test(s))return 'Főétel';return 'Egyéb fogás'};
function groups(data){let map=new Map();for(let r of (data['Dashboard adatfolyam']||[]).slice(1)){if(!r[0]||!r[5]||r[28]!=='Önálló fogás'||/savanyúság|köret\s*\/\s*saláta/i.test(String(r[4]||'')))continue;let id=r[25]||r[0];if(!map.has(id))map.set(id,{id,rest:r[2],rows:[],text:'',category:cat(r)});let g=map.get(id);g.rows.push(r);g.text+=' '+[r[5],r[6],r[29],r[30],r[31]].filter(Boolean).join(' ')}return [...map.values()]}
const med=a=>{let b=a.slice().sort((x,y)=>x-y),n=b.length;return n?(n%2?b[(n-1)/2]:(b[n/2-1]+b[n/2])/2):null};function chart(items,max,label='db'){return items.length?items.map(([k,v])=>`<div class="viz-row"><span>${esc(k)}</span><div class="viz-track"><div class="viz-bar" style="width:${Math.max(1,v/max*100)}%"></div></div><b>${v} ${label}</b></div>`).join(''):'<p>Nincs a szűrésnek megfelelő adat.</p>'}function render(data){const all=groups(data),rs=[...new Set(all.map(x=>x.rest))].sort((a,b)=>a.localeCompare(b,'hu'));let filtered=all.filter(g=>(!restaurant||g.rest===restaurant)&&(!query||g.text.toLocaleLowerCase('hu').includes(query.toLocaleLowerCase('hu')))&&(pizza||g.category!=='Pizza / pinsa'));let byRest=new Map(),byCat=new Map();for(let g of filtered){byRest.set(g.rest,(byRest.get(g.rest)||0)+1);byCat.set(g.category,(byCat.get(g.category)||0)+1)}let restaurants=[...byRest].sort((a,b)=>b[1]-a[1]),cats=[...byCat].sort((a,b)=>b[1]-a[1]);let families=new Map();for(let g of filtered){let family=String(g.rows[0][27]||'').trim();if(!family||/^(egyéb|főétel|előétel|desszert)$/i.test(family))continue;if(!families.has(family))families.set(family,new Set());families.get(family).add(g.rest)}let dishFamilies=[...families].map(([k,v])=>[k,v.size]).filter(x=>x[1]>1).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'hu')).slice(0,15);let matching=terms.map(([name,re])=>{let hit=filtered.filter(g=>re.test(g.text));return {name,hit,places:new Set(hit.map(g=>g.rest)).size}}).filter(x=>x.hit.length).sort((a,b)=>b.places-a.places||b.hit.length-a.hit.length);let prices=new Map();for(let g of filtered){let vals=[...new Set(g.rows.filter(r=>r[40]==='Közölt ár'&&r[42]!=='Kizárva – ár tisztázandó'&&r[37]==='Helyszíni').map(r=>Number(r[7])).filter(n=>n>0))];if(vals.length!==1)continue;if(!prices.has(g.category))prices.set(g.category,[]);prices.get(g.category).push(vals[0])}let p=[...prices].filter(([k,v])=>v.length>=3).sort((a,b)=>b[1].length-a[1].length);let ingredient=matching.map(x=>[x.name,x.places]);return `<div class="eyebrow">ÉTLAPOK / ADATVIZUALIZÁCIÓ</div><h1>Mi szerepel az étlapokon?</h1><p class="section-intro">Mely fogástípusok és alapanyagok fordulnak elő a mintában, és milyen árakon? Válassz éttermet, vagy keress alapanyagot.</p><div class="warning"><b>Kínálat, nem kereslet.</b> A lista részleges, különböző méretű és időpontú étlapokból áll. A ritka itt csak azt jelenti: kevés vizsgált helyen találtuk meg. Nem mutatja, mit és mennyit rendelnek.</div><p><a href="#" data-go="1">Részletes étlapkereső megnyitása →</a></p><div class="form viz-filters"><label>Étterem<select id="viz-rest"><option value="">Minden feldolgozott étterem</option>${rs.map(x=>`<option ${restaurant===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Alapanyag vagy fogás<input id="viz-query" value="${esc(query)}" placeholder="pl. kacsa, sütőtök"></label><label class="viz-check"><input id="viz-pizza" type="checkbox" ${pizza?'checked':''}> Pizza / pinsa is látszódjon</label><button id="viz-reset" class="small-btn">Szűrők törlése</button></div><p class="muted">${filtered.length} egyedi fogáscsoport · ${byRest.size} étterem · csak önálló fogások · eltérő időpontú megfigyelések · a régi Elefánt-étlap történeti</p><div class="grid2"><section class="panel"><h2>Mekkora a feldolgozott kínálat?</h2><p class="muted">Önálló fogáscsoportok száma éttermenként. A hiányos feldolgozás torzíthatja az összevetést.</p>${chart(restaurants,restaurants[0]?.[1]||1,'fogás')}</section><section class="panel"><h2>Milyen típusú fogások szerepelnek?</h2><p class="muted">Fogáscsoportok becsült kategóriák szerint. A különböző profilú éttermek aránya befolyásolja a képet.</p>${chart(cats,cats[0]?.[1]||1,'fogás')}</section></div><section class="panel"><h2>Mely fogáscsaládok fordulnak elő több helyen?</h2><p class="muted">A forrástáblában megadott fogáscsalád alapján; az azonos nevű kategóriák helyenként eltérő receptet takarnak. Csak a legalább két étteremben szereplő családokat mutatjuk.</p>${chart(dishFamilies,Math.max(1,byRest.size),'hely')}</section><section class="panel"><h2>Mi hány étterem étlapján fordul elő?</h2><p class="muted">A vízszintes sáv az éttermek számát mutatja; a fogásszám külön látszik a részletekben. A kiemelt alapanyagokat kulcsszavakból keressük az ételnévben és a forrásleírásban: nem teljes körű összetevőlista.</p>${chart(ingredient,Math.max(1,byRest.size),'hely')}<details><summary>Fogásszámok és példák megnyitása</summary>${matching.map(x=>`<details><summary>${esc(x.name)} · ${x.places} hely · ${x.hit.length} fogáscsoport</summary><ul>${x.hit.slice(0,25).map(g=>`<li>${esc(g.rest)}${g.rows[0][1]==='E01'?' (korábbi étlap, történeti)':''}: ${esc(g.rows[0][5])} · ${g.rows[0][7]?fmt(g.rows[0][7])+' Ft':'ár nem ismert'} · <a href="${esc(g.rows[0][16]||'https://docs.google.com/spreadsheets/d/1eigqlKCEuAGTrBA-96k44CB51-EedJh_FJafi2lb_ww/edit')}" target="_blank" rel="noopener">forrás ↗</a></li>`).join('')}</ul>${x.hit.length>25?'<p>Az első 25 példa látható. Szűkíts étteremre vagy keress rá a fogásra.</p>':''}</details>`).join('')}</details></section><section class="panel"><h2>Milyen árak látszanak kategóriánként?</h2><p class="muted">Kiírt helyszíni árak, szervizdíj nélkül, forintban. A recept, adag, köret és érvényesség eltérhet. A bizonytalan és több eltérő árral szereplő fogáscsoportok kimaradnak. Minimum három árnál mutatunk összehasonlítást.</p><div class="scroll"><table><thead><tr><th>Kategória</th><th>Minimum</th><th>Medián</th><th>Maximum</th><th>Minta</th></tr></thead><tbody>${p.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${fmt(Math.min(...v))} Ft</td><td><b>${fmt(med(v))} Ft</b></td><td>${fmt(Math.max(...v))} Ft</td><td>${v.length} fogás</td></tr>`).join('')||'<tr><td colspan="5">Nincs legalább három összehasonlítható ár a szűrésben.</td></tr>'}</tbody></table></div></section><details class="panel"><summary>Mit számolunk, és mi marad ki?</summary><p>Forrás: <a target="_blank" rel="noopener" href="https://docs.google.com/spreadsheets/d/1eigqlKCEuAGTrBA-96k44CB51-EedJh_FJafi2lb_ww/edit#gid=615031026">Étlap tételek munkalap ↗</a>. Egy megfigyelési alap: étteremhez kötött kanonikus fogásazonosító; ha nincs, rekordazonosító. A változatokat azonos csoportba rendezzük, így nem növelik többször a fogások számát. Az adatforrás a Dashboard adatfolyam. A felárakat, italpárosításokat, csomagokat és külön köreteket nem számoljuk önálló fogásként. A másik, november 9-i étlapgyűjteményt nem adjuk hozzá az átfedések miatt. Az Elefánt korábbi étlapja történeti referencia; csatornája ellenőrzendő, ezért a helyszíni árstatisztikából kimarad.</p><p>A kategóriákat szöveges szabályokkal közelítjük, a konyhai profilok nem teljesen összehasonlíthatók. A felsorolt alapanyagok nem fednek le mindent, az írásmód és a hiányzó leírás miatt téves vagy hiányzó egyezés előfordulhat. Az árak nem alkalmasak önmagukban árazási döntésre.</p></details>`}
window.renderMenuViz=render;window.mountMenuViz=(data,rerender)=>{let el=document.getElementById('viz-rest');if(!el)return;el.onchange=e=>{restaurant=e.target.value;rerender()};document.getElementById('viz-pizza').onchange=e=>{pizza=e.target.checked;rerender()};document.getElementById('viz-reset').onclick=()=>{restaurant='';query='';pizza=false;rerender()};document.getElementById('viz-query').oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;rerender();let x=document.getElementById('viz-query');x.focus();x.setSelectionRange(pos,pos)}}})();
